"""Current three-family silhouette review, from actual models and native captures."""
from pathlib import Path
import json,html
ROOT=Path(__file__).resolve().parents[2];OUT=ROOT/'development/levels/hollow-creek'
r=json.loads((OUT/'tailored-fabric.json').read_text(encoding='utf-8'));v=json.loads((ROOT/'development/levels/verification/hollow-creek-tailored-shape.json').read_text(encoding='utf-8'))
page=['<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Camp Hollow Creek — tailored fabric review</title><style>body{background:#151d1c;color:#e4e7df;font:17px/1.6 system-ui;max-width:1250px;margin:auto;padding:28px}a{color:#a8d2c2}h1,h2{color:#e7d2a0}img{width:100%;height:auto}figure{margin:8px 0 24px}figcaption{padding:7px}.compare{display:grid;grid-template-columns:1fr 1fr;gap:16px}.gate{border-left:4px solid #ba9a60;padding:12px;background:#27332c}@media(max-width:750px){.compare{grid-template-columns:1fr}}</style><h1>Camp Hollow Creek</h1><p>24 October2026 · Tent and bedding silhouette refinement</p><p class="gate">Three new source models replace rigid fabric with tension sag, restrained folds and supported sewn lines. The dome has a real continuous arched doorway. Eight tents and seven rolled bags receive the geometry in the current native scene. Ground, placements, fitted floors, frames and anchors retain their authored coordinates.</p>']
page+=['<h2>Current scene, matched cameras</h2>']
for name in ['west','east']:
 page.append(f'<div class="compare"><figure><img src="../previews/hollow-creek/tailored-before-{name}-native-fitout.png" alt="Previous authored native scene"><figcaption>Previous fabric geometry</figcaption></figure><figure><img src="../previews/hollow-creek/tailored-{name}-native-fitout.png" alt="Current tailored native scene"><figcaption>Current tailored fabric geometry</figcaption></figure></div>')
for name,label in [('bedding','Placed stitched bedding'),('site','Current whole site')]:page.append(f'<figure><img loading="lazy" src="../previews/hollow-creek/tailored-{name}-native-fitout.png" alt="{label}"><figcaption>{label} · Native scene capture</figcaption></figure>')
page+=['<h2>Original model comparisons</h2>']
for a in r['assets']:
 id=a['id'];old=a['previous_source'];title=id.replace('level_camp_','').replace('_tailored','').replace('_',' ')
 page.append(f'<h3>{html.escape(title)}</h3><div class="compare"><figure><img loading="lazy" src="../previews/{old}.png" alt="Previous model"><figcaption>Previous source</figcaption></figure><figure><img loading="lazy" src="../previews/{id}.png" alt="Tailored source model"><figcaption>{a["triangles"]} actual triangles · <a href="../blender/{id}.blend">Editable model</a> · <a href="../../../assets/runtime/models/{id}.glb">Runtime GLB</a></figcaption></figure></div>')
seams=sum(a['sewn_support_probes'] for a in v['assets']);thickness=sum(a['thickness_probes'] for a in v['assets'])
page.append(f'<h2>Physical checks and limits</h2><p>Closed actual cloth shells;{seams} seam-support probes;{thickness} shell thickness rays (nominal8mm). All232864 fitted floor vertices on8 tents retain exact world positions, and788 other scene meshes retain geometry/placement.72 positive native roof/floor rays prevent missing or buried canopies from passing on clearance alone.</p>')
page+=['<p>Native fit:10377 protected-route samples,363 ritual samples,72 floor contacts,1640 crouch-entry probes,18 bedding contacts,126 foundation/ramp samples,1250 barrier rays and9 culvert terrain rays pass. Three GLBs reimport under unchanged50k/4MB caps (23444 triangles combined); the actual game reader passes1080 independent per-material UV/PNG pixel checks. The prior14 authored model families and8 legacy equipment meshes retain their passing loader checks.</p><p class="gate">These images are native/studio captures, not gameplay screenshots. Runtime map/collision/render/circuits/AI/LAN, layered water, hiding activation, human/LOD/performance and final story/loose-physics/Easter-egg gates remain open. Firewood silhouettes, foliage/boundary models and remaining gear still need refinement. The existing vehicle color-count assertion remains separately open as DEV-060.</p><p><a href="hollow-creek-tailored.blend">Current native scene</a> · <a href="tailored-fabric.json">Sources/instances</a> · <a href="../verification/hollow-creek-tailored-shape.json">Independent physical checks</a> · <a href="../verification/hollow-creek-tailored-fit.json">Native fit checks</a> · <a href="AUTHORED_REVIEW.html">Previous surface review</a> · <a href="../../../beckenburg-development-gallery.html">Shared gallery</a></p></html>']
(OUT/'TAILORED_REVIEW.html').write_text('\n'.join(page)+'\n',encoding='utf-8')
banner='<p class="gate"><a href="TAILORED_REVIEW.html">Latest: tent and bedding silhouette refinement — current native review</a></p>'
for name in ['EXPANDED_REVIEW.html','REFINEMENT_REVIEW.html','AUTHORED_REVIEW.html']:
 p=OUT/name;text=p.read_text(encoding='utf-8')
 if banner not in text:text=text.replace('<h1>',banner+'<h1>',1)
 p.write_text(text,encoding='utf-8')
print('Built current tailored fabric/native review')
